      "depends_on": [
        4
      ]
    },
    {
      "id": 6,
      "claim": "Dividing by 3 gives x = 60.",
      "evidence": "Dividing both sides of 3x = 180 by 3 to isolate x.",
      "weight": 0.10,
      "depends_on": [
        5
      ]
    }
  ],
